CREATE DATABASE IF NOT EXISTS minipj_db;
GRANT ALL PRIVILEGES ON minipj_db.* TO 'scoula'@'%';
FLUSH PRIVILEGES;

USE minipj_db;

-- 기존 테이블 정리 (FK 때문에 asset 먼저)
DROP TABLE IF EXISTS asset;
DROP TABLE IF EXISTS product;
DROP TABLE IF EXISTS member;

-- 1) member (회원)
CREATE TABLE member (
    member_id   BIGINT       PRIMARY KEY AUTO_INCREMENT,
    username    VARCHAR(50)  NOT NULL UNIQUE,
    password    VARCHAR(100) NOT NULL,
    nickname    VARCHAR(50)  NOT NULL UNIQUE,
    `character` VARCHAR(20),
    gender      VARCHAR(10),
    age         INT,
    region      VARCHAR(50),
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 2) asset (자산)
CREATE TABLE asset (
    asset_id   BIGINT       PRIMARY KEY AUTO_INCREMENT,
    member_id  BIGINT       NOT NULL,
    category   VARCHAR(30)  NOT NULL,
    asset_type VARCHAR(100) NOT NULL,
    amount     BIGINT       NOT NULL,
    created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (member_id) REFERENCES member(member_id)
);

-- 3) product (예적금 상품)
CREATE TABLE product (
    product_id   BIGINT       PRIMARY KEY AUTO_INCREMENT,
    product_name VARCHAR(100) NOT NULL,
    bank         VARCHAR(50)  NOT NULL,
    product_type VARCHAR(20)  NOT NULL,
    base_rate    DECIMAL(4,2),
    max_rate     DECIMAL(4,2),
    period_month INT,
    min_amount   BIGINT,
    max_amount   BIGINT,
    min_period   INT,
    max_period   INT,
    feature      VARCHAR(300),
    description  VARCHAR(500),
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 4) 상품 데이터 (4대 은행 × 15개 = 60개)

